<template>
  <div class="video-soundtrack">
    <!-- 顶部导航栏 -->
    <div class="page-header">
      <h1 class="page-title">{{ t('soundtrack') }}</h1>
    </div>

    <!-- 主内容区域 -->
    <div class="page-content">
      <!-- 视频上传区域 -->
      <div class="upload-section">
        <div class="upload-container">
          <div class="video-preview-area">
            <MobileVideoUploader
              ref="videoUploaderRef"
              :video-url="formData.uploadedVideoUrl"
              :max-size="50 * 1024 * 1024"
              accept="video/mp4,video/avi,video/mov,video/wmv,video/flv,video/webm"
              @onUploadSuccess="handleVideoUploadSuccess"
              @onUploadRemove="handleVideoUploadRemove"
            />
          </div>
        </div>
      </div>

      <!-- 配乐类型选择区域 -->
      <div class="soundtrack-type-section">
        <div class="soundtrack-type-options">
          <div 
            class="soundtrack-option"
            :class="{ 'soundtrack-option--selected': formData.soundtrackType === 'automatic' }"
            @click="selectSoundtrackType('automatic')"
          >
            <div class="radio-wrapper">
              <div class="radio-circle" :class="{ 'radio-circle--selected': formData.soundtrackType === 'automatic' }">
                <div v-if="formData.soundtrackType === 'automatic'" class="radio-dot"></div>
              </div>
              <span class="radio-label">{{ t('musicAccordingToVideo') }}</span>
            </div>
          </div>
          <div 
            class="soundtrack-option"
            :class="{ 'soundtrack-option--selected': formData.soundtrackType === 'custom' }"
            @click="selectSoundtrackType('custom')"
          >
            <div class="radio-wrapper">
              <div class="radio-circle" :class="{ 'radio-circle--selected': formData.soundtrackType === 'custom' }">
                <div v-if="formData.soundtrackType === 'custom'" class="radio-dot"></div>
              </div>
              <span class="radio-label">{{ t('customSoundtrack') }}</span>
            </div>
          </div>
        </div>
      </div>

      <!-- 音乐风格选择区域 (当选择 custom 时显示) -->
      <div v-if="formData.soundtrackType === 'custom'" class="music-style-section">
        <div class="section-label">{{ t('style') }}</div>
        <div class="music-style-grid">
          <div 
            v-for="style in musicStylesRef" 
            :key="style.value"
            class="music-style-tag"
            :class="{ 'music-style-tag--selected': formData.selectedStyle === style.value }"
            @click="selectMusicStyle(style.value)"
          >
            {{ style.label }}
          </div>
        </div>
      </div>

      <!-- 情绪选择区域 (当选择 custom 时显示) -->
      <div v-if="formData.soundtrackType === 'custom'" class="mood-selection-section">
        <div class="section-label">{{ t('mood') }}</div>
        <div class="mood-grid">
          <div 
            v-for="mood in moodOptionsRef" 
            :key="mood.value"
            class="mood-tag"
            :class="{ 'mood-tag--selected': formData.selectedMood === mood.value }"
            @click="selectMood(mood.value)"
          >
            {{ mood.label }}
          </div>
        </div>
      </div>

      <!-- 错误提示 -->
      <div v-if="formError" class="form-error-section">
        <div class="form-error">{{ formError }}</div>
      </div>
    </div>

    <!-- 底部按钮占位区域 -->
    <div class="empty-quality-selector-area" :style="{ height: '80px' }"></div>

    <!-- 底部操作按钮区域 -->
    <div class="quality-selector-area">
      <div class="generate-button-wrapper">
        <div class="generate-button-container">
          <button
            class="generate-button"
            :class="{ 'generate-button--disabled': isButtonDisabled }"
            :disabled="isButtonDisabled"
            @click="handleGenerate"
          >
            <MobileLImg v-show="isGenerating" class="loading-icon" :src="'/static/mobile_images/msg-think-loading.png'" w="16px" h="16px"></MobileLImg>
            {{ isGenerating ? t('generating') : t('generateVideo') }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, onMounted, onBeforeUnmount } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileVideoUploader from '@/mobile/components/mobile-video-uploader.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { musicStyles, moodOptions } from '@/types/panel-options';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import router from '@/router';
import { VIDEO_OPERATIONS } from '@/types/media-tool';

// 变量区域
const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 当前模块的 key
const MODULE_KEY = VIDEO_OPERATIONS.SOUNDTRACK;

// 常量
const musicStylesRef = ref(musicStyles);
const moodOptionsRef = ref(moodOptions);

// 响应式变量
const videoUploaderRef = ref(null);
const isGenerating = ref(false);
const formError = ref('');
const currentTaskId = ref(null);

// 表单数据
const formData = reactive({
  soundtrackType: 'automatic', // 'automatic' | 'custom'
  selectedStyle: '', // 只能选择一个音乐风格
  selectedMood: '', // 只能选择一个情绪
  uploadedVideoUrl: '',
  uploadedPosterUrl: '',
  uploadedVideoInfo: null,
});

// 计算属性区域
const isButtonDisabled = computed(() => {
  // 正在生成时禁用按钮
  if (isGenerating.value) {
    return true;
  }
  
  // 必须上传视频
  if (!formData.uploadedVideoUrl) {
    return true;
  }
  
  // 自动模式下，有视频即可生成
  if (formData.soundtrackType === 'automatic') {
    return false;
  }
  
  // 自定义模式下需要至少选择一个风格或情绪
  return !formData.selectedStyle && !formData.selectedMood;
});

// 点击事件区域
const selectSoundtrackType = (type) => {
  formData.soundtrackType = type;
  formError.value = '';
};

const selectMusicStyle = (style) => {
  formData.selectedStyle = formData.selectedStyle === style ? '' : style;
  formError.value = '';
};

const selectMood = (mood) => {
  formData.selectedMood = formData.selectedMood === mood ? '' : mood;
  formError.value = '';
};

const handleGenerate = async () => {
  // 验证表单
  if (!formData.uploadedVideoUrl) {
    formError.value = t('pleaseUploadVideo');
    return;
  }
  
  if (formData.soundtrackType === 'custom' && !formData.selectedStyle && !formData.selectedMood) {
    formError.value = t('pleaseSelectStyleOrMood');
    return;
  }

  try {
    isGenerating.value = true;
    formError.value = '';
    
    // 准备请求数据
    const requestData = {
      soundtrackType: formData.soundtrackType,
      selectedStyle: formData.selectedStyle,
      selectedMood: formData.selectedMood,
      videoInfo: formData.uploadedVideoInfo,
      videoUrl: formData.uploadedVideoUrl
    };

    console.log('Video soundtrack with data:', requestData);
    
    // TODO: 调用真实的API (暂时忽略，接口不支持)
    // const result = await apiGeneration.videoSoundtrack(requestData);
    
    // 模拟API响应
    const apiResult = {
      task_id: `task_soundtrack_${Date.now()}`,
      status: 'pending'
    };
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = apiResult.task_id;
    meta.type = TaskType.VIDEO;
    addTaskToPolling(apiResult.task_id, TaskType.VIDEO);
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
  } catch (error) {
    console.error('Video soundtrack failed:', error);
    formError.value = t('generationFailed');
    isGenerating.value = false;
  }
};

// 自定义事件区域
const handleVideoUploadSuccess = (result) => {
  console.log('Video upload success:', result);
  formData.uploadedVideoUrl = result.url;
  formData.uploadedPosterUrl = result.posterUrl;
  formData.uploadedVideoInfo = result;
  formError.value = '';
};

const handleVideoUploadRemove = () => {
  console.log('Video upload removed');
  formData.uploadedVideoUrl = '';
  formData.uploadedPosterUrl = '';
  formData.uploadedVideoInfo = null;
  formError.value = '';
};

// 业务逻辑区域
// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 构造结果数据
    const result = {
      id: Date.now(),
      soundtrackType: formData.soundtrackType,
      selectedStyle: formData.selectedStyle,
      selectedMood: formData.selectedMood,
      originalVideo: formData.uploadedVideoInfo,
      uploadedVideoInfo: formData.uploadedVideoInfo,
      videoUrl: res.result?.media_list?.[0]?.file_url || formData.uploadedVideoUrl,
      posterUrl: formData.uploadedPosterUrl,
      enhancedVideo: res.result?.media_list?.[0]?.file_url || 'soundtrack-video.mp4',
      generatedAt: new Date().toISOString()
    };
    
    // TODO: 处理生成成功事件，可能需要导航到结果页面
    console.log('Soundtrack generation completed:', result);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    console.error('Soundtrack generation failed:', res);
    formError.value = t('generationFailed');
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Video soundtrack progress: ${res.res.progress}%`);
  }
};

// 数据解析区域
// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    // 设置默认视频URL和相关信息
    formData.uploadedVideoUrl = result?.videoUrl ? result.videoUrl : formData.uploadedVideoUrl;
    formData.uploadedPosterUrl = result?.posterUrl ? result.posterUrl : formData.uploadedPosterUrl;
    formData.uploadedVideoInfo = result?.videoInfo ? result.videoInfo : formData.uploadedVideoInfo;
    formData.soundtrackType = result?.soundtrackType ? result.soundtrackType : formData.soundtrackType;
    formData.selectedStyle = result?.selectedStyle ? result.selectedStyle : formData.selectedStyle;
    formData.selectedMood = result?.selectedMood ? result.selectedMood : formData.selectedMood;
    
    // 清除生成结果，避免重复使用
    mediaStore.clearGenerationResult(MODULE_KEY);
  }
};

// 初始化方法区域
const initData = () => {
  // 检测Pinia中是否有生成的视频数据
  loadGenerationResult();
};

const initEvent = () => {
  // 绑定媒体任务事件监听器
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
};

// 周期函数区域
onMounted(() => {
  initData();
  initEvent();
});

onBeforeUnmount(() => {
  // 清理事件监听器
  clearMediaTaskEventListeners();
  // 清除生成结果
  mediaStore.clearGenerationResult(MODULE_KEY);
});
</script>

